window.TAB_TEMPLATES['analyzer'] = "<div class=\"analyzer-hero-card\">\n  <div style=\"font-size:18px; font-weight:800; color:#0f172a; margin-bottom:4px;\">\n    &#128373; 360&#176; Stock Intelligence Dossier\n  </div>\n  <div style=\"font-size:13px; color:#475569; margin-bottom:14px;\">\n    Search any NSE listed equity stock or F&amp;O derivative to view synthesized confluence: Market Signal, Quality/Score breakdown, AI Quant model stance, and Final Actionable Verdict.\n  </div>\n\n  <div style=\"position:relative; max-width:600px;\">\n    <div style=\"display:flex; gap:8px;\">\n      <input\n        type=\"text\"\n        id=\"analyzerInput\"\n        placeholder=\"Search any share symbol or name (e.g. RELIANCE, TCS, MANORAMA)...\"\n        oninput=\"onAnalyzerSearchInput(this.value)\"\n        onkeydown=\"onAnalyzerSearchKeyDown(event)\"\n        style=\"flex:1; padding:10px 14px; font-size:14px; border:2px solid #cbd5e1; border-radius:8px; outline:none;\"\n      >\n      <button onclick=\"triggerAnalyzerSearch()\" class=\"analyzer-search-btn\">\n        Analyze\n      </button>\n    </div>\n    <div id=\"analyzerSuggestions\" class=\"analyzer-suggestions\" style=\"display: none;\"></div>\n  </div>\n\n  <div style=\"margin-top:12px; display:flex; gap:6px; flex-wrap:wrap; align-items:center;\">\n    <span style=\"font-size:12px; font-weight:700; color:#64748b;\">Quick Stocks:</span>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('RELIANCE')\">RELIANCE</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('TCS')\">TCS</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('HDFCBANK')\">HDFCBANK</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('INFY')\">INFY</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('MANORAMA')\">MANORAMA</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('SBIN')\">SBIN</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('ICICIBANK')\">ICICIBANK</button>\n    <button class=\"analyzer-chip\" onclick=\"selectAnalyzerStock('ZOMATO')\">ZOMATO</button>\n  </div>\n</div>\n\n<div id=\"analyzerDossier\">";
